insert into public.hh_meditation_catalog_v1 (
youtube_id,title,creator,source_kind,source_url,source_evidence_url,audio_language,
duration_hint_minutes,duration_basis,content_type,goals,goal_weights,subtopics,
user_situations,desired_states,techniques,time_of_day,posture,experience_level,intensity,
spiritual_style,music_style,voice_style,safety_flags,claims_risk,metadata_confidence,
editorial_status,embed_status,rights_status,review_notes,metadata_checked_at)
select
r->>'youtube_id',r->>'title',r->>'creator',r->>'source_kind',r->>'source_url',
r->>'source_evidence_url',r->>'audio_language',(r->>'duration_hint_minutes')::smallint,
r->>'duration_basis',r->>'content_type',array(select jsonb_array_elements_text(r->'goals')),r->'goal_weights',array(select jsonb_array_elements_text(r->'subtopics')),
array(select jsonb_array_elements_text(r->'user_situations')),array(select jsonb_array_elements_text(r->'desired_states')),array(select jsonb_array_elements_text(r->'techniques')),r->>'time_of_day',
r->>'posture',r->>'experience_level',r->>'intensity',r->>'spiritual_style',
r->>'music_style',r->>'voice_style',array(select jsonb_array_elements_text(r->'safety_flags')),
r->>'claims_risk',r->>'metadata_confidence',r->>'editorial_status',
r->>'embed_status',r->>'rights_status',r->>'review_notes',now()
from source
on conflict (youtube_id) do nothing;

